    expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "33.33"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "7.50"})).toBe(true);
    const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "B"}));
    await ui.loadSheet(pg_uma, sheet);
    await ui.setSetting(pg_uma, "parent", `${sheet}-p`);
    await ui.setSetting(pg_uma, "pot", "100.00");
    expect(await ui.setSettingDated(pg_uma, "rounding", "half-even", "2026-03-01", "half-even")).toBe(true);
    await ui.setSetting(pg_uma, "review-threshold", "1.50");
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "5.00"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "12.50"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "20.00", "from": "2026-03-01"})).toBe(true);
    expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
    expect(await ui.addPeriod(pg_uma, {"name": "P2", "from": "2026-03-16", "to": "2026-03-31"})).toBe(true);
    expect(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "C"})).toBeNull();
    const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "C", "terms": "20", "tags": "c"}));
    expect(await ui.editPerson(pg_uma, p_ben, {"terms": "20", "termsFrom": "2026-03-01"})).toBe(true);
    const c_ben_0 = ui.must(await ui.addClaim(pg_uma, p_ben, {"amount": "25.00", "date": "2026-02-10", "ref": "R-2"}));
    expect(await ui.inlineGrade(pg_uma, p_ben, "A")).toBe(true);
    expect(await ui.retire(pg_uma, p_ben, "2026-03-09")).toBe(true);
    await ui.showRetired(pg_uma, true);
    expect(await ui.statement(pg_uma, p_ben)).toBe(true);
    expect(await ui.claimEditOpen(pg_uma, c_ben_0)).toBe(true);
    const pg_wes = await ui.userPage(browser, "wes", sheet);
    await ui.showRetired(pg_wes, true);
    expect(await ui.claimEditOpen(pg_wes, c_ben_0)).toBe(false);
    await ui.refresh(pg_uma);
    expect(await ui.claimEditSave(pg_uma, c_ben_0, {"amount": "20.00"})).toBe(true);
    expect(await ui.periodAction(pg_uma, "P2", "close")).toBe(true);
    await ui.expectAuditView(pg_uma, "Ben", [
      `CLAIM_EDITED sheet=${sheet} by=uma person=Ben amount=20.00 date=2026-02-10`,
      `STATEMENT sheet=${sheet} by=uma name=Ben due-total=0.00 claims=0`,
