  /** Put a hold on the person from the row's from-date (blank: the sheet's today) to its to-date
   *  (blank: no end). */
  protected async hold(person: PersonView, fromInput: HTMLInputElement, toInput: HTMLInputElement): Promise<void> {
    const sheet = this.session.sheet();
    if (!sheet || this.holding() !== null) return;
    this.personError.set(null);
    this.patronError.set(null);
    const from = fromInput.value.trim();
    const to = toInput.value.trim();
    if ((from !== '' && !DATE.test(from)) || (to !== '' && !DATE.test(to))) {
      this.personError.set({ id: person.id, message: 'Enter the hold dates as yyyy-mm-dd.' });
      return;
    }
    if (to !== '' && to < (from !== '' ? from : sheet.today)) {
      this.personError.set({ id: person.id, message: 'A hold cannot end before it starts.' });
      return;
    }
    this.holding.set(person.id);
    try {
      const changed = await this.api.hold(sheet.id, person.id, from === '' ? null : from, to === '' ? null : to);
      if (this.session.sheet()?.id !== sheet.id) return;
      this.people.update((list) => list.map((p) => (p.id === changed.id ? changed : p)));
      fromInput.value = '';
      toInput.value = '';
    } catch {
      if (this.session.sheet()?.id === sheet.id) {
        this.personError.set({ id: person.id, message: 'The person could not be put on hold.' });
      }
    } finally {
      this.holding.set(null);
  /** Every grade the person was given, the one from the beginning of time first, then by from-date. */
  grades: GradeView[];
  /** Bumped on each save; an edit is sent with the version its editor loaded. */
  version: number;
  /** True as soon as a retirement date is set, whatever the date. */
  retired: boolean;
  /** The date the person is retired from, or null while they are not retired. */
  retiredFrom: string | null;
  /** Every past retirement of the person, in the order they were unretired. */
  retirements: RetirementView[];
  /** Whether the person has any hold, whatever its dates. */
  held: boolean;
  /** Every hold put on the person, by from-date: their open claims dated within one, unless a
   *  statement binds them, count in no live total. */
  holds: HoldView[];
  /** The ids of the other people on the sheet the person has named as patrons, in the order named. */
  patronIds: number[];
  /** Whether the signed-in user watches the person. */
  watched: boolean;
  /** The person's own terms in force on the sheet's today, in days, or null when they use their
   *  grade's, else the sheet's. */

    public PersonService(PersonRepository people, PersonPatronRepository patrons, PersonWatchRepository watches,
            PersonAliasRepository aliases, SheetService sheets, NameTree tree, Rollup rollup, Audit audit,
            SheetTagRepository sheetTags) {
        this.people = people;
        this.patrons = patrons;
        this.watches = watches;
        this.aliases = aliases;
        this.sheets = sheets;
        this.tree = tree;
        this.rollup = rollup;
        this.audit = audit;
        this.sheetTags = sheetTags;
    }

    /** The sheet's people in list order. */
    @Transactional(readOnly = true)
    public List<Person> list(String sheetId) {
        return people.findInListOrder(sheetId);
    }

    /** The ids of the sheet's people whose name or an alias is used on another sheet of its tree. */
    @Transactional(readOnly = true)
    public Set<Long> clashingIds(String sheetId) {
        Set<String> elsewhere = tree.keysElsewhere(sheetId, NameTree.NO_ONE);
        return list(sheetId).stream().filter(p -> NameTree.clashes(p, elsewhere)).map(Person::getId)
                .collect(Collectors.toSet());
    }

    /** Whether the person's name or an alias is used on another sheet of their sheet's tree. */
    @Transactional(readOnly = true)
    public boolean isClashing(Person person) {
        return tree.clashes(person);
    }

    /** The ids of each person's patrons on the sheet, by person, in the order they were named; a person
     *  with no patrons is left out. */
    @Transactional(readOnly = true)
    public Map<Long, List<Long>> patronIds(String sheetId) {
        Map<Long, List<Long>> by = new LinkedHashMap<>();
        for (PersonPatron patron : patrons.findBySheetIdOrderByIdAsc(sheetId)) {
            by.computeIfAbsent(patron.getPersonId(), p -> new ArrayList<>()).add(patron.getPatronId());
