/** Edit a person. */
@PutMapping("/{id}")
public PersonView update(@PathVariable @NotBlank @Size(max = 100) String sheetId, @PathVariable long id,
        @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Valid PersonEdit form) {
    return view(service.update(sheetId.trim(), SignedInUser.name(user), id, form.version(),
            form.name(), form.grade(), form.gradeFrom(), termsOf(form.terms()), form.termsFrom(),
            form.contact(), form.tags(), false), user);
    Person person = people.findByIdAndSheetId(id, sheetId)
            .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
    return update(sheetId, user, id, version, name, grade, gradeFrom, terms, contact,
            String.join(",", person.getTags()));
}

/** Edit a person as {@link #update(String, String, long, long, String, Grade, LocalDate, Integer, String)},
 *  giving them the tags (comma separated; blank or null: none). */
@Transactional
public Person update(String sheetId, String user, long id, long version, String name, Grade grade,
        LocalDate gradeFrom, Integer terms, String contact, String tags) {
    return update(sheetId, user, id, version, name, grade, gradeFrom, terms, contact, tags, false);
}

/** Edit a person as {@link #update(String, String, long, long, String, Grade, LocalDate, Integer, String, String)};
 *  an explicit grade (a bulk grade) is recorded from its from-date even when already in force then. */
@Transactional
public Person update(String sheetId, String user, long id, long version, String name, Grade grade,
        LocalDate gradeFrom, Integer terms, String contact, String tags, boolean explicitGrade) {
    return update(sheetId, user, id, version, name, grade, gradeFrom, terms, null, contact, tags, explicitGrade);
}

/** Edit a person as {@link #update(String, String, long, long, String, Grade, LocalDate, Integer, String, String, boolean)},
 *  recording their terms from the terms' from-date, keeping those recorded from other dates (none:
 *  from the beginning of time). */
@Transactional
}
const contact = value.contact.trim().toLowerCase();
if (contact !== '' && this.people().some((p) => p.id !== id && p.contact === contact)) {
  this.error.set('That contact is already in use on the sheet.');
  void this.reread(sheet.id);
  return;
}
this.saving.set(true);
const editor = this.editorsOpened;
try {
  if (id === null) {
    const added = await this.api.add(sheet.id,
      { name: value.name.trim(), grade: value.grade, terms,
        termsFrom: termsFrom === '' ? null : termsFrom, contact: value.contact,
        tags: value.tags });
    if (this.session.sheet()?.id === sheet.id) this.people.update((list) => [...list, added]);
  } else {
    const saved = await this.api.update(sheet.id, id,
      { name: value.name.trim(), grade: value.grade, gradeFrom: gradeFrom === '' ? null : gradeFrom, terms,
        termsFrom: termsFrom === '' ? null : termsFrom,
        contact: value.contact, tags: value.tags, version: this.editingVersion() });
    if (this.session.sheet()?.id === sheet.id) {
      this.people.update((list) => list.map((p) => (p.id === saved.id ? saved : p)));
      // An editor opened on the person while this save ran edits the version it stored.
      if (editor !== this.editorsOpened && this.editingId() === saved.id) this.editingVersion.set(saved.version);
    }
  }
  if (this.session.sheet()?.id === sheet.id && editor === this.editorsOpened) this.reset();
} catch (e) {
  if (id !== null && e instanceof HttpErrorResponse && e.status === 412) {
    await this.showCurrent(sheet.id, id);

